using TownOfHost;using TownOfHost.Roles.Core;using AmongUs.GameOptions;
class Program{
 static int passed;
 static void Check(bool value){if(!value)throw new Exception("display assertion");}
 static void Test(string name,Action a){Options.Reset();OptionItem.AllOptions.Clear();RoleSettingsDisplay.Reset();a();passed++;Console.WriteLine("PASS "+name);}
 static OptionItem Add(CustomRoles r,TabGroup tab,From from=From.TownOfHost_hamo){SimpleRoleInfo.Create(typeof(RoleBase),p=>new RoleBase(),r,()=>RoleTypes.Crewmate,CustomRoleTypes.Crewmate,800000+(int)r,null,"test",from:from);var o=new OptionItem{Id=OptionItem.AllOptions.Count,CustomRole=r,Tab=tab,Value=37};OptionItem.AllOptions.Add(o);return o;}
 static void Main(){
 Test("new neutral roles directly precede Eliminator",()=>{Add(CustomRoles.Idol,TabGroup.NeutralRoles);Add(CustomRoles.Eliminator,TabGroup.NeutralRoles);Add(CustomRoles.Informant,TabGroup.NeutralRoles);Add(CustomRoles.LifeSaver,TabGroup.NeutralRoles);var order=RoleSettingsDisplay.DisplayOptions(TabGroup.NeutralRoles).Select(o=>o.CustomRole).ToArray();Check(order.Take(3).SequenceEqual(new[]{CustomRoles.LifeSaver,CustomRoles.Informant,CustomRoles.Eliminator}));});
 Test("new impostors precede Nova in reverse creation order",()=>{foreach(var r in new[]{CustomRoles.Nova,CustomRoles.Slugger,CustomRoles.Pusher,CustomRoles.Gimlet,CustomRoles.Bloodlust,CustomRoles.EvilButtoner,CustomRoles.Cleaner})Add(r,TabGroup.ImpostorRoles);var order=RoleSettingsDisplay.DisplayOptions(TabGroup.ImpostorRoles).Select(o=>o.CustomRole);Check(order.SequenceEqual(new[]{CustomRoles.Cleaner,CustomRoles.EvilButtoner,CustomRoles.Bloodlust,CustomRoles.Gimlet,CustomRoles.Pusher,CustomRoles.Slugger,CustomRoles.Nova}));});
 Test("recent section header is contiguous",()=>{var a=Add(CustomRoles.LifeSaver,TabGroup.NeutralRoles);var b=Add(CustomRoles.Informant,TabGroup.NeutralRoles);Check(RoleSettingsDisplay.HeaderFor(a.Tab,a).Key=="recent-imports");Check(RoleSettingsDisplay.HeaderFor(b.Tab,b).Key=="recent-imports");});
 Test("MOD mode preserves origin rather than recency grouping",()=>{var a=Add(CustomRoles.Slugger,TabGroup.ImpostorRoles,From.SuperNewRoles);var b=Add(CustomRoles.Bloodlust,TabGroup.ImpostorRoles,From.TownOfHost_K);RoleSettingsDisplay.Toggle();Check(RoleSettingsDisplay.HeaderFor(a.Tab,a).Key!="recent-imports");Check(RoleSettingsDisplay.HeaderFor(b.Tab,b).Key!="recent-imports");});
 Test("recency does not change persisted collection/IDs/values",()=>{var a=Add(CustomRoles.Nova,TabGroup.ImpostorRoles);var b=Add(CustomRoles.Slugger,TabGroup.ImpostorRoles);var original=OptionItem.AllOptions.ToArray();for(int i=0;i<100;i++){_ =RoleSettingsDisplay.DisplayOptions(a.Tab).ToArray();RoleSettingsDisplay.Toggle();}Check(OptionItem.AllOptions.SequenceEqual(original));Check(a.Id==0&&b.Id==1&&a.Value==37&&b.Value==37);});
 Test("notice has normal add-on recency header",()=>{var a=Add(CustomRoles.Notice,TabGroup.Addons);Check(RoleSettingsDisplay.HeaderFor(a.Tab,a).Key=="recent-imports");});
 Test("recent section collapse is local display state",()=>{var a=Add(CustomRoles.Cleaner,TabGroup.ImpostorRoles);var h=RoleSettingsDisplay.HeaderFor(a.Tab,a);RoleSettingsDisplay.ToggleHeader(a.Tab,h);Check(RoleSettingsDisplay.IsCollapsed(a.Tab,h));Check(a.Value==37);RoleSettingsDisplay.ToggleHeader(a.Tab,h);Check(!RoleSettingsDisplay.IsCollapsed(a.Tab,h));});
 Test("Shell Destroyer origin remains Nebula",()=>{var a=Add(CustomRoles.Destroyer,TabGroup.ImpostorRoles,From.NebulaontheShip);Check(CustomRoles.Destroyer.GetRoleInfo().From==From.NebulaontheShip);Check(RoleSettingsDisplay.HeaderFor(a.Tab,a).Key!="recent-imports");});
 Console.WriteLine($"HAMO44004_DISPLAY_RESULT {passed} passed, 0 failed (actual registration and display planner)");}}
